(4529694, 652969, 55838, '<td valign="top">LOVE your title!  : )  It makes her unusual position have meaning.  Cute shot - border is a bit heavy for my taste but you get an extra point for making me laugh with that title! 7</td>', 'LOVE your title!  : )  It makes her unusual position have meaning.  Cute shot - border is a bit heavy for my taste but you get an extra point for making me laugh with that title! 7', '2008-03-01 07:41:22.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4529698, 652583, 55838, '<td valign="top">Very pretty model and I like the contrast in the field.  I think the image would have been stronger with just the middle girl.  Hopefully these are triplets.</td>', 'Very pretty model and I like the contrast in the field.  I think the image would have been stronger with just the middle girl.  Hopefully these are triplets.', '2008-03-01 07:44:50.000000', NULL, 1),
(4529708, 652698, 55838, '<td valign="top">Very sweet little face &amp; beautiful eyes.  I like the perspective and the stray hairs are great! 7</td>', 'Very sweet little face & beautiful eyes.  I like the perspective and the stray hairs are great! 7', '2008-03-01 07:52:23.000000', NULL, 1),
(4529712, 648777, 55838, '<td valign="top">Of course this is fabulous...the colors and reflections...brilliant!  Very nicely done. 9</td>', 'Of course this is fabulous...the colors and reflections...brilliant!  Very nicely done. 9', '2008-03-01 07:54:00.000000', NULL, 1),
(4529719, 652738, 55838, '<td valign="top">Very beautiful image.  I like how you framed the eyes and the focus and colortones are wonderful.  A very interesting face!  8</td>', 'Very beautiful image.  I like how you framed the eyes and the focus and colortones are wonderful.  A very interesting face!  8', '2008-03-01 07:55:23.000000', NULL, 1),
(4529725, 652978, 55838, '<td valign="top">Fun shot - full of personality!  Made me smile.  My eyes would prefer a sharper focus and a little more contrast in your conversion to b&amp;w. Very pretty model and a funny title.</td>', 'Fun shot - full of personality!  Made me smile.  My eyes would prefer a sharper focus and a little more contrast in your conversion to b&w. Very pretty model and a funny title.', '2008-03-01 07:58:05.000000', NULL, 1),
(4529733, 648149, 55838, '<td valign="top">Very nice environmental portrait.  Love the composition.  The bright white fence is a little distracting...perhaps next time you should tear that one down and build a new dark wood toned fence before you shoot. :)</td>', 'Very nice environmental portrait.  Love the composition.  The bright white fence is a little distracting...perhaps next time you should tear that one down and build a new dark wood toned fence before you shoot. :)', '2008-03-01 08:01:01.000000', NULL, 1),
(4529739, 653073, 55838, '<td valign="top">Great shot (and from my home state of NY - YAY!!!)!  So full of fun stuff to look at.  Wonderful contrast and great b&amp;w conversion.  This well composed real life shot gets high marks from me and adding to favorites.</td>', 'Great shot (and from my home state of NY - YAY!!!)!  So full of fun stuff to look at.  Wonderful contrast and great b&w conversion.  This well composed real life shot gets high marks from me and adding to favorites.', '2008-03-01 08:03:25.000000', NULL, 1),
(4529741, 650475, 55838, '<td valign="top">Now of course this should be a poster!  A terrific moment captured.  Perhaps it''s my monitor but my eyes would like a little more contrasty darkness in their skin &amp; hair.  Downright hilarious!  8</td>', 'Now of course this should be a poster!  A terrific moment captured.  Perhaps it''s my monitor but my eyes would like a little more contrasty darkness in their skin & hair.  Downright hilarious!  8', '2008-03-01 08:05:57.000000', NULL, 1),
(4529753, 652105, 88561, '<td valign="top">Way too bright.  Focus needs to be much sharper.  By the title, the stop sign is your subject, but I find the storefronts to be more of a subject.</td>', 'Way too bright.  Focus needs to be much sharper.  By the title, the stop sign is your subject, but I find the storefronts to be more of a subject.', '2008-03-01 08:21:59.000000', NULL, 1),
(4529756, 652565, 55838, '<td valign="top">A cool different kind of kid shot.  Love that swirling hair and the little hint of face underneath.  7</td>', 'A cool different kind of kid shot.  Love that swirling hair and the little hint of face underneath.  7', '2008-03-01 08:24:44.000000', NULL, 1),
(4529760, 651752, 55838, '<td valign="top">Fantastic portrait.  I love the darkness and the contrasting silvery light.  Great expression.  IMHO the border takes away from this wonderful shot - no border or small black might work better for my eyes. 8</td>', 'Fantastic portrait.  I love the darkness and the contrasting silvery light.  Great expression.  IMHO the border takes away from this wonderful shot - no border or small black might work better for my eyes. 8', '2008-03-01 08:28:20.000000', NULL, 1),
(4529761, 650119, 88561, '<td valign="top">I''ve come back to this shot a number of times before commenting.  I really like the pose, the lines of the dancers.  I can''t fully put my finger on it, but I find the two tone background does not compliment the shot - for me anyway.  I find the panel/mailbox and downspout to distract my eye from the woman.</td>', 'I''ve come back to this shot a number of times before commenting.  I really like the pose, the lines of the dancers.  I can''t fully put my finger on it, but I find the two tone background does not compliment the shot - for me anyway.  I find the panel/mailbox and downspout to distract my eye from the woman.', '2008-03-01 08:31:41.000000', NULL, 1),
(4529762, 652974, 61577, '<td valign="top">Could be a twin of my cat Blue</td>', 'Could be a twin of my cat Blue', '2008-03-01 08:32:09.000000', NULL, 1),
(4529766, 645843, 88561, '<td valign="top">Sorry, it''s kinda blah.  Nothing pops at me, nor do I find a subject of interest.  Colors are drab.  Smokestack is bright.</td>', 'Sorry, it''s kinda blah.  Nothing pops at me, nor do I find a subject of interest.  Colors are drab.  Smokestack is bright.', '2008-03-01 08:35:23.000000', NULL, 1),
(4529782, 651977, 84124, '<td valign="top">First one I''m voting on in this challenge, and I''ll bet it does well.  I like everything about this photo.</td>', 'First one I''m voting on in this challenge, and I''ll bet it does well.  I like everything about this photo.', '2008-03-01 08:42:54.000000', NULL, 1),
(4529789, 653052, 84124, '<td valign="top">I''ve spent more time looking at this one than any other in the challenge (besides my own).  Much of the photo simply looks too photoshopped, but I''m not sure that''s a bad thing as the junker clearly takes you back to a bygone era, and the background has an almost mythical appeal that takes you there as well.  All in all, it''s a great shot.  Would love to see the original after the challenge.  8</td>', 'I''ve spent more time looking at this one than any other in the challenge (besides my own).  Much of the photo simply looks too photoshopped, but I''m not sure that''s a bad thing as the junker clearly takes you back to a bygone era, and the background has an almost mythical appeal that takes you there as well.  All in all, it''s a great shot.  Would love to see the original after the challenge.  8', '2008-03-01 08:47:55.000000', NULL, 1),
(4529790, 649420, 88561, '<td valign="top">I like the light coming through the clouds.  But if I hadn''t read the title, I don''t think I would know it was the Statue of Liberty, Ellis island and the Depot.  I really like the thougt process of the photo, but your subject (statue) is too far away.  I wish I could score higher then I did.</td>', 'I like the light coming through the clouds.  But if I hadn''t read the title, I don''t think I would know it was the Statue of Liberty, Ellis island and the Depot.  I really like the thougt process of the photo, but your subject (statue) is too far away.  I wish I could score higher then I did.', '2008-03-01 08:49:17.000000', NULL, 1),
(4529794, 652645, 84124, '<td valign="top">great composition.  I''d say the photo really "takes me there" but I''d have a hard time getting past the additional 10" of snow packed up against my door ;-)</td>', 'great composition.  I''d say the photo really "takes me there" but I''d have a hard time getting past the additional 10" of snow packed up against my door ;-)', '2008-03-01 08:50:11.000000', NULL, 1),
(4529800, 652473, 84124, '<td valign="top">There are so many great shots in this challenge, this one among them, so simple and so well done.  The color, the bare trees, the translucent clouds, well done.</td>', 'There are so many great shots in this challenge, this one among them, so simple and so well done.  The color, the bare trees, the translucent clouds, well done.', '2008-03-01 08:51:38.000000', NULL, 1),
(4529802, 652485, 88561, '<td valign="top">Stunning!</td>', 'Stunning!', '2008-03-01 08:51:56.000000', NULL, 1),
(4529817, 644380, 88561, '<td valign="top">Very nice.  I would maybe crop the branch out on the left, a little distracting and doesn''t add to the photo.</td>', 'Very nice.  I would maybe crop the branch out on the left, a little distracting and doesn''t add to the photo.', '2008-03-01 09:01:03.000000', NULL, 1),
(4529821, 643851, 88136, '<td valign="top">hair in the eye is kinda distracting. good idea and comp.</td>', 'hair in the eye is kinda distracting. good idea and comp.', '2008-03-01 09:02:10.000000', NULL, 1),
(4529822, 651518, 15711, '<td valign="top">Very artful and different. I love the eye.</td>', 'Very artful and different. I love the eye.', '2008-03-01 09:03:10.000000', NULL, 1),
(4529823, 652969, 88136, '<td valign="top">oh this is the cuuutest baby in the whole world :D-8</td>', 'oh this is the cuuutest baby in the whole world :D-8', '2008-03-01 09:03:17.000000', NULL, 1),
(4529825, 652693, 88136, '<td valign="top">lol</td>', 'lol', '2008-03-01 09:03:54.000000', NULL, 1),
