(4531701, 651547, 86799, '<td valign="top">The uneven light highlights the face O.K., but it''s a little distracting.  Almost looks unintended.  Still nice, though.</td>', 'The uneven light highlights the face O.K., but it''s a little distracting.  Almost looks unintended.  Still nice, though.', '2008-03-01 23:36:14.000000', NULL, 1),
(4531706, 645504, 90113, '<td valign="top">Beautiful sunset and mood.  I might have tried to clone out that thin cloud that seems to be piercing his head.  Not sure if it would be possible with the complexity of the sky, but I''d give it a try.</td>', 'Beautiful sunset and mood.  I might have tried to clone out that thin cloud that seems to be piercing his head.  Not sure if it would be possible with the complexity of the sky, but I''d give it a try.', '2008-03-01 23:38:45.000000', NULL, 1),
