(4531974, 644255, 80326, '<td valign="top">It looks like over sharpened from here.</td>', 'It looks like over sharpened from here.', '2008-03-02 03:49:29.000000', NULL, 1),
(4531980, 652297, 80326, '<td valign="top">It looks like the monty phyton meaning of life dinner sketch restaurant. It''s a tad dark, would be good to see more detail in the BG.</td>', 'It looks like the monty phyton meaning of life dinner sketch restaurant. It''s a tad dark, would be good to see more detail in the BG.', '2008-03-02 03:53:33.000000', NULL, 1),
