(4540205, 651820, 90495, '<td valign="top">I''ll guess this is the female. Never seen them this colour. You caught it well. They''re nervous critters, hard to capture.</td>', 'I''ll guess this is the female. Never seen them this colour. You caught it well. They''re nervous critters, hard to capture.', '2008-03-05 09:58:27.000000', NULL, 1),
(4540548, 652275, 78196, '<td valign="top">Wow. Incredibly striking.</td>', 'Wow. Incredibly striking.', '2008-03-05 11:40:33.000000', NULL, 1),
(4540550, 652572, 78196, '<td valign="top">Wonderful portrait and perfectly controlled DoF.</td>', 'Wonderful portrait and perfectly controlled DoF.', '2008-03-05 11:41:01.000000', NULL, 1),
(4540568, 647945, 78196, '<td valign="top">Heartfelt and wonderful. The lighting is almost perfect - just watch out for the blown highlights on the left side of her face.</td>', 'Heartfelt and wonderful. The lighting is almost perfect - just watch out for the blown highlights on the left side of her face.', '2008-03-05 11:44:58.000000', NULL, 1),
(4540644, 652913, 30982, '<td valign="top">This looks like one of Bear''s shooting locations.  I love the blue.</td>', 'This looks like one of Bear''s shooting locations.  I love the blue.', '2008-03-05 12:20:12.000000', NULL, 1),
(4540647, 648299, 30982, '<td valign="top">An entirely awesome composition.  Thank you for not removing the lens flares.</td>', 'An entirely awesome composition.  Thank you for not removing the lens flares.', '2008-03-05 12:20:40.000000', NULL, 1),
(4540648, 647023, 30982, '<td valign="top">Great shot!!</td>', 'Great shot!!', '2008-03-05 12:20:52.000000', NULL, 1),
(4540654, 648704, 30982, '<td valign="top">She is indeed.  And a wonderful natural setting.  I like the glow on this.</td>', 'She is indeed.  And a wonderful natural setting.  I like the glow on this.', '2008-03-05 12:23:26.000000', NULL, 1),
(4540655, 652728, 30982, '<td valign="top">This is delightful and charming.</td>', 'This is delightful and charming.', '2008-03-05 12:23:53.000000', NULL, 1),
