(4540659, 652993, 30982, '<td valign="top">This is quite intriguing to me.  At first glance, she''s almost unreal, unreachable - he''s a bit more in the shadows, a bit more average and real.  The looks they have - she toward the camera, he toward her, emphasize this.  Nice addition of the guitar.</td>', 'This is quite intriguing to me.  At first glance, she''s almost unreal, unreachable - he''s a bit more in the shadows, a bit more average and real.  The looks they have - she toward the camera, he toward her, emphasize this.  Nice addition of the guitar.', '2008-03-05 12:26:58.000000', NULL, 1),
(4540663, 652590, 30982, '<td valign="top">They look like prehistoric animals in some slow graceful ballet, heading toward somewhere.</td>', 'They look like prehistoric animals in some slow graceful ballet, heading toward somewhere.', '2008-03-05 12:27:37.000000', NULL, 1),
(4540667, 645837, 30982, '<td valign="top">Oooh!  I''m going to see them in May, I hope.  I love the shadowed horse in front.</td>', 'Oooh!  I''m going to see them in May, I hope.  I love the shadowed horse in front.', '2008-03-05 12:29:19.000000', NULL, 1),
(4540668, 653109, 30982, '<td valign="top">Excellent find!</td>', 'Excellent find!', '2008-03-05 12:29:40.000000', NULL, 1),
(4540675, 652442, 30982, '<td valign="top">Statue or real?  Either way, this is a fascinating picture..</td>', 'Statue or real?  Either way, this is a fascinating picture..', '2008-03-05 12:32:59.000000', NULL, 1),
(4540686, 652466, 83313, '<td valign="top">Maybe HDR or a little heavy on the PP, but I like it.</td>', 'Maybe HDR or a little heavy on the PP, but I like it.', '2008-03-05 12:36:54.000000', NULL, 1),
(4540689, 642667, 83313, '<td valign="top">Neat looking, though the composition does not really seem to lead me anywhere.</td>', 'Neat looking, though the composition does not really seem to lead me anywhere.', '2008-03-05 12:37:47.000000', NULL, 1),
(4540696, 652714, 83313, '<td valign="top">The boy looks odd, as if you really had to work the curves to bring the detail out of a backlit image.</td>', 'The boy looks odd, as if you really had to work the curves to bring the detail out of a backlit image.', '2008-03-05 12:39:20.000000', NULL, 1),
(4540702, 652280, 30982, '<td valign="top">Hee!  I like the smiley faces from the bifocals!</td>', 'Hee!  I like the smiley faces from the bifocals!', '2008-03-05 12:42:05.000000', NULL, 1),
(4540703, 651170, 83313, '<td valign="top">Some serious banding going on in the sky,and a slight vignetting that I am not caring for. The actual area of the sunset/sunrise on the horizon also seems grainy ad indistinct. Not really sure what to suggest on this one, other than maybe a different perspective or alternate settings when shooting it.</td>', 'Some serious banding going on in the sky,and a slight vignetting that I am not caring for. The actual area of the sunset/sunrise on the horizon also seems grainy ad indistinct. Not really sure what to suggest on this one, other than maybe a different perspective or alternate settings when shooting it.', '2008-03-05 12:42:34.000000', NULL, 1),
(4540709, 650583, 83313, '<td valign="top">Neat looking. The houses in the distance seem to be demanding attention, but they are too small. However, since they are the brightest spot in the image, they draw my eye away form the real subject of the crosses in the foreground.</td>', 'Neat looking. The houses in the distance seem to be demanding attention, but they are too small. However, since they are the brightest spot in the image, they draw my eye away form the real subject of the crosses in the foreground.', '2008-03-05 12:44:51.000000', NULL, 1),
(4540710, 641618, 83313, '<td valign="top">I like the texture and detail of the jeans and hand. The t shirt has some blown highlights, though that may have been intentional.</td>', 'I like the texture and detail of the jeans and hand. The t shirt has some blown highlights, though that may have been intentional.', '2008-03-05 12:46:27.000000', NULL, 1),
(4540712, 652785, 83313, '<td valign="top">Now, this is cool looking.</td>', 'Now, this is cool looking.', '2008-03-05 12:47:45.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4540716, 641899, 83313, '<td valign="top">The upper edge of the river bank tends to draw the eye away from the falls a bit, otherwise good.</td>', 'The upper edge of the river bank tends to draw the eye away from the falls a bit, otherwise good.', '2008-03-05 12:50:35.000000', NULL, 1),
(4540717, 643851, 83313, '<td valign="top">The eyes look a little to heavily pimped, otherwise I like this.</td>', 'The eyes look a little to heavily pimped, otherwise I like this.', '2008-03-05 12:51:30.000000', NULL, 1),
(4540721, 652845, 83313, '<td valign="top">Good use of the flash. Would have been good to either see her face, or have her turned so it was not visible at all.</td>', 'Good use of the flash. Would have been good to either see her face, or have her turned so it was not visible at all.', '2008-03-05 12:53:02.000000', NULL, 1),
(4540729, 646809, 83313, '<td valign="top">Knock, Knock, JPEG police here. Please open up...<br/> <br/>Your file size is small, less than half of what it could have been for this challenge. This indicates lots of JPEG compression. You have surely lost a lot of detail to compression. Check the settings for that in your image editor when you save your files.<br/> <br/>White balance needs some tweaking as well, to get rid of the yellowish cast from the inside lights.<br/> <br/>Love the truck.</td>', 'Knock, Knock, JPEG police here. Please open up... Your file size is small, less than half of what it could have been for this challenge. This indicates lots of JPEG compression. You have surely lost a lot of detail to compression. Check the settings for that in your image editor when you save your files. White balance needs some tweaking as well, to get rid of the yellowish cast from the inside lights. Love the truck.', '2008-03-05 12:58:28.000000', NULL, 1),
(4540732, 652775, 83313, '<td valign="top">Really nice scene, though I''m not sure about that large trunk in the forground. It is a good element, but seems too much in front of the rest of the scene.</td>', 'Really nice scene, though I''m not sure about that large trunk in the forground. It is a good element, but seems too much in front of the rest of the scene.', '2008-03-05 13:00:21.000000', NULL, 1),
(4540738, 649340, 83313, '<td valign="top">The background is very grainy. The Buddah figure is good, but Maybe a different view or lighting might show off the detail of the metal surface a bit better.</td>', 'The background is very grainy. The Buddah figure is good, but Maybe a different view or lighting might show off the detail of the metal surface a bit better.', '2008-03-05 13:02:09.000000', NULL, 1),
(4540741, 653088, 83313, '<td valign="top">The face is a bit hidden in shadows, but otherwise, good.</td>', 'The face is a bit hidden in shadows, but otherwise, good.', '2008-03-05 13:04:02.000000', NULL, 1),
(4540746, 650908, 83313, '<td valign="top">Not sure if I like this or not. The people in the corner are  not quite big enough to be the main subject, but they are there and compete with the dirt bike. It''s different, though. I''m still not sure.</td>', 'Not sure if I like this or not. The people in the corner are  not quite big enough to be the main subject, but they are there and compete with the dirt bike. It''s different, though. I''m still not sure.', '2008-03-05 13:06:27.000000', NULL, 1),
(4540749, 643964, 83313, '<td valign="top">Quite a bit different than rush hour in Dallas. The goats appear to actually get out of the way, and I''ll bet there are no tolls!</td>', 'Quite a bit different than rush hour in Dallas. The goats appear to actually get out of the way, and I''ll bet there are no tolls!', '2008-03-05 13:08:20.000000', NULL, 1),
(4540752, 652848, 83313, '<td valign="top">Nice stuff. Like the way the hair spills.</td>', 'Nice stuff. Like the way the hair spills.', '2008-03-05 13:09:29.000000', NULL, 1),
(4540754, 644441, 83313, '<td valign="top">Nice and bold, perhaps a bit too centered for my prefs.</td>', 'Nice and bold, perhaps a bit too centered for my prefs.', '2008-03-05 13:10:21.000000', NULL, 1),
(4540760, 651181, 83313, '<td valign="top">I like the iced over look. The red boat is partially cut off, so I am not sure if the subject is the boat or the bridge. The comp draws my attention to the bridge, but the red boat grabs my eye.</td>', 'I like the iced over look. The red boat is partially cut off, so I am not sure if the subject is the boat or the bridge. The comp draws my attention to the bridge, but the red boat grabs my eye.', '2008-03-05 13:12:04.000000', NULL, 1),
(4540768, 652948, 83313, '<td valign="top">Good details showing on this. Not sure if I care for the desat look, but I would have to see it in color to really know for sure.</td>', 'Good details showing on this. Not sure if I care for the desat look, but I would have to see it in color to really know for sure.', '2008-03-05 13:13:59.000000', NULL, 1),
(4540773, 646887, 83313, '<td valign="top">Nice ice! I like the rich colors coming through the ice and the branch.</td>', 'Nice ice! I like the rich colors coming through the ice and the branch.', '2008-03-05 13:15:44.000000', NULL, 1),
(4540976, 652894, 30982, '<td valign="top">And it''s a raven with three heads.</td>', 'And it''s a raven with three heads.', '2008-03-05 14:12:27.000000', NULL, 1),
