(4543319, 652297, 83313, '<td valign="top">Has a very old time feel about it. Like it''s a scene from an old b/w movie.</td>', 'Has a very old time feel about it. Like it''s a scene from an old b/w movie.', '2008-03-06 13:09:33.000000', NULL, 1),
(4543324, 652345, 83313, '<td valign="top">amazing how a long exposure can make a night scene so bright looking. I''ll be looking to see what your settings for this were after the challenge.</td>', 'amazing how a long exposure can make a night scene so bright looking. I''ll be looking to see what your settings for this were after the challenge.', '2008-03-06 13:11:44.000000', NULL, 1),
(4543331, 652691, 83313, '<td valign="top">Great use of the fog, and I really like the perspective as well.</td>', 'Great use of the fog, and I really like the perspective as well.', '2008-03-06 13:12:44.000000', NULL, 1),
(4543336, 645419, 83313, '<td valign="top">I guess if I knew who this was, the title might make sense. I feel like I am supposed to know, but I don''t, so my apologies.</td>', 'I guess if I knew who this was, the title might make sense. I feel like I am supposed to know, but I don''t, so my apologies.', '2008-03-06 13:15:22.000000', NULL, 1),
(4543337, 652584, 83313, '<td valign="top">Clean crisp and bold.</td>', 'Clean crisp and bold.', '2008-03-06 13:16:19.000000', NULL, 1),
(4543349, 650756, 83313, '<td valign="top">The slight shadows an the eagles face is the only real issue here, but these things don''t usually pose for you. (Tilt your beak some, now spread your wings nice and wide...)</td>', 'The slight shadows an the eagles face is the only real issue here, but these things don''t usually pose for you. (Tilt your beak some, now spread your wings nice and wide...)', '2008-03-06 13:19:43.000000', NULL, 1),
(4543351, 652971, 83313, '<td valign="top">Pretty nice. Lot of fine detail that does not come through in 720 pixels, unfortunately.</td>', 'Pretty nice. Lot of fine detail that does not come through in 720 pixels, unfortunately.', '2008-03-06 13:20:58.000000', NULL, 1),
(4543357, 648599, 83313, '<td valign="top">Really nice, but it does not seem to stand out from a lot of other bold sunsets. Perhaps a closer silhouette of that cactus against the sky would make it a more unique shot.</td>', 'Really nice, but it does not seem to stand out from a lot of other bold sunsets. Perhaps a closer silhouette of that cactus against the sky would make it a more unique shot.', '2008-03-06 13:23:35.000000', NULL, 1),
(4543369, 651415, 83313, '<td valign="top">Is the title what she said about the photographer? (Sorry, I had to make a silly comment, but she''s cute and it''s a nice portrait of her.)</td>', 'Is the title what she said about the photographer? (Sorry, I had to make a silly comment, but she''s cute and it''s a nice portrait of her.)', '2008-03-06 13:27:30.000000', NULL, 1),
(4543377, 642826, 83313, '<td valign="top">He loves his baby brother, doesn''t he? It''s strikes me as just a quick snapshot of a sweet moment, but it is certainly good for what it is.</td>', 'He loves his baby brother, doesn''t he? It''s strikes me as just a quick snapshot of a sweet moment, but it is certainly good for what it is.', '2008-03-06 13:29:50.000000', NULL, 1),
(4543407, 653001, 89341, '<td valign="top">Beautiful</td>', 'Beautiful', '2008-03-06 13:44:12.000000', NULL, 1),
(4543453, 652345, 31606, '<td valign="top">Very nice , serene image.  I love everything about it.</td>', 'Very nice , serene image.  I love everything about it.', '2008-03-06 14:08:25.000000', NULL, 1),
(4543454, 652568, 31606, '<td valign="top">In my top three.  Very beautiful shot.</td>', 'In my top three.  Very beautiful shot.', '2008-03-06 14:08:42.000000', NULL, 1),
