(4543474, 648777, 31606, '<td valign="top">Very beautiful.  Lovely deep blues.  Very pleasing to the eye.</td>', 'Very beautiful.  Lovely deep blues.  Very pleasing to the eye.', '2008-03-06 14:13:09.000000', NULL, 1),
(4543479, 651764, 31606, '<td valign="top">lovin it.  I love the close up and the focus is spot on.</td>', 'lovin it.  I love the close up and the focus is spot on.', '2008-03-06 14:13:41.000000', NULL, 1),
