(4543541, 652273, 77192, '<td valign="top">I don''t know if it''s my screen, but you have some horrible "jaggies" on the lighthouse, and the clump of snoe the immediate foreground. Perhaps a little less sharpening?</td>', 'I don''t know if it''s my screen, but you have some horrible "jaggies" on the lighthouse, and the clump of snoe the immediate foreground. Perhaps a little less sharpening?', '2008-03-06 14:44:47.000000', NULL, 1),
(4543544, 652982, 77192, '<td valign="top">nice angle to shoot from. clever. Where did you find a crossing with only two cars though? ;-)</td>', 'nice angle to shoot from. clever. Where did you find a crossing with only two cars though? ;-)', '2008-03-06 14:46:15.000000', NULL, 1),
(4543547, 645418, 77192, '<td valign="top">too much coluor for me. I think you needed to cut back on the saturation slider.</td>', 'too much coluor for me. I think you needed to cut back on the saturation slider.', '2008-03-06 14:46:56.000000', NULL, 1),
(4543550, 653028, 77192, '<td valign="top">nice abstract, love the patterns in this one. It might be worth experimenting with different angles/framings, to get the black "line" running differently through the picture. It''s good how it is though.</td>', 'nice abstract, love the patterns in this one. It might be worth experimenting with different angles/framings, to get the black "line" running differently through the picture. It''s good how it is though.', '2008-03-06 14:48:53.000000', NULL, 1),
(4543557, 645486, 77192, '<td valign="top">I wouldn''t have been able to see he was moving without the title, to be honest. I''d maybe suggest a different angle?</td>', 'I wouldn''t have been able to see he was moving without the title, to be honest. I''d maybe suggest a different angle?', '2008-03-06 14:52:00.000000', NULL, 1),
(4543560, 652907, 77192, '<td valign="top">Clever find, nice angle and patterns. I think the shadows in the foreground could do with lightening though, just to remove distraction</td>', 'Clever find, nice angle and patterns. I think the shadows in the foreground could do with lightening though, just to remove distraction', '2008-03-06 14:54:09.000000', NULL, 1),
