(4543584, 653031, 69102, '<td valign="top">Lovely image. Very serene and great toning.</td>', 'Lovely image. Very serene and great toning.', '2008-03-06 15:01:00.000000', NULL, 1),
(4543592, 653113, 69102, '<td valign="top">This is fantastic. Very intriguing image with great tones and nice use of grain. Perhaps a slightly tighter crop to get rid of the vase(?) lines on either side - but then they may actually add something to the image (I go back and forth).</td>', 'This is fantastic. Very intriguing image with great tones and nice use of grain. Perhaps a slightly tighter crop to get rid of the vase(?) lines on either side - but then they may actually add something to the image (I go back and forth).', '2008-03-06 15:03:37.000000', NULL, 1),
(4543593, 652984, 77192, '<td valign="top">haha it''s not fooling anyone ;-)</td>', 'haha it''s not fooling anyone ;-)', '2008-03-06 15:03:39.000000', NULL, 1),
(4543595, 651180, 69102, '<td valign="top">Fantastically captured. Great light, movement, and processing. Is this on the Columbia Gorge?</td>', 'Fantastically captured. Great light, movement, and processing. Is this on the Columbia Gorge?', '2008-03-06 15:04:13.000000', NULL, 1),
(4543596, 645384, 69102, '<td valign="top">Lovely and intriguing image.</td>', 'Lovely and intriguing image.', '2008-03-06 15:04:35.000000', NULL, 1),
(4543599, 652593, 27437, '<td valign="top">The borders are a bit distracting to me. They aren''t consistent in width. I would play around a bit more with that to see if you can make it work. Maybe if there were one border inside the picture to act as a pseudo frame?</td>', 'The borders are a bit distracting to me. They aren''t consistent in width. I would play around a bit more with that to see if you can make it work. Maybe if there were one border inside the picture to act as a pseudo frame?', '2008-03-06 15:05:11.000000', NULL, 1),
(4543600, 645830, 27437, '<td valign="top">I like this photo, but the baby looks frightened in this shot.</td>', 'I like this photo, but the baby looks frightened in this shot.', '2008-03-06 15:06:50.000000', NULL, 1),
(4543603, 645830, 77192, '<td valign="top">lol</td>', 'lol', '2008-03-06 15:08:50.000000', NULL, 1),
