(4543629, 652716, 36999, '<td valign="top">nice color &amp; comp, seems like it could be a bit sharper but that may be due to the resize for DPC.</td>', 'nice color & comp, seems like it could be a bit sharper but that may be due to the resize for DPC.', '2008-03-06 15:25:23.000000', NULL, 1),
(4543641, 651139, 36999, '<td valign="top">this is lovely.  Nicecolor palatte.</td>', 'this is lovely.  Nicecolor palatte.', '2008-03-06 15:30:28.000000', NULL, 1),
(4543692, 652907, 811, '<td valign="top">Kinda took me a minute to see what i was looking at.  cool perpspective.</td>', 'Kinda took me a minute to see what i was looking at.  cool perpspective.', '2008-03-06 15:56:34.000000', NULL, 1),
(4543693, 652897, 811, '<td valign="top">Beautiful.  Great colors, focus, composition.</td>', 'Beautiful.  Great colors, focus, composition.', '2008-03-06 15:57:26.000000', NULL, 1),
(4543694, 653007, 811, '<td valign="top">I like the colors and *motion* of this.  It seems a bit cramp at the top, though.</td>', 'I like the colors and *motion* of this.  It seems a bit cramp at the top, though.', '2008-03-06 15:58:39.000000', NULL, 1),
(4543697, 642826, 811, '<td valign="top">It is a bit noisy, a bit "red" and I think a tighter crop on the right would make it more balanced.  But, it is a precious capture and one that you (or whoever the parents are) will always treasure, regardless of what "I" think.</td>', 'It is a bit noisy, a bit "red" and I think a tighter crop on the right would make it more balanced.  But, it is a precious capture and one that you (or whoever the parents are) will always treasure, regardless of what "I" think.', '2008-03-06 16:00:24.000000', NULL, 1),
(4543705, 643622, 811, '<td valign="top">Good composition, and I like the backlighting, in a sense, effect.  It seems a bit flat to me, though.  Maybe a touch of contrast would help.</td>', 'Good composition, and I like the backlighting, in a sense, effect.  It seems a bit flat to me, though.  Maybe a touch of contrast would help.', '2008-03-06 16:04:53.000000', NULL, 1),
(4543716, 642912, 811, '<td valign="top">I like the composition and colors, but it looks like you may have been a little heavy with the noise reduction</td>', 'I like the composition and colors, but it looks like you may have been a little heavy with the noise reduction', '2008-03-06 16:10:10.000000', NULL, 1),
(4543723, 652996, 30982, '<td valign="top">I''m not exactly sure why I''m drawn to this, but drawn to it I am.</td>', 'I''m not exactly sure why I''m drawn to this, but drawn to it I am.', '2008-03-06 16:14:41.000000', NULL, 1),
(4543724, 652893, 30982, '<td valign="top">They are the best of friends, yes?  And even if not, you''ve presented them as such.</td>', 'They are the best of friends, yes?  And even if not, you''ve presented them as such.', '2008-03-06 16:16:00.000000', NULL, 1),
(4543729, 653016, 30982, '<td valign="top">An excellent capture of a wonderful moment.  I like this a lot.</td>', 'An excellent capture of a wonderful moment.  I like this a lot.', '2008-03-06 16:17:38.000000', NULL, 1),
(4543731, 653041, 30982, '<td valign="top">Beautifully set up and photographed.</td>', 'Beautifully set up and photographed.', '2008-03-06 16:18:27.000000', NULL, 1),
(4543732, 651752, 30982, '<td valign="top">A very good portrait which I''m hoping you''ve had printed and framed.</td>', 'A very good portrait which I''m hoping you''ve had printed and framed.', '2008-03-06 16:18:48.000000', NULL, 1),
(4543733, 652605, 30982, '<td valign="top">This is marvelous.  Wonderful glimpse of childhood and completely timeless.</td>', 'This is marvelous.  Wonderful glimpse of childhood and completely timeless.', '2008-03-06 16:19:21.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4543735, 642404, 30982, '<td valign="top">Excellent light, intriguing photograph.  Very well done.</td>', 'Excellent light, intriguing photograph.  Very well done.', '2008-03-06 16:19:43.000000', NULL, 1),
(4543737, 652919, 30982, '<td valign="top">Wonderfully composed and great work to bring out the detail in the feathers throughout.</td>', 'Wonderfully composed and great work to bring out the detail in the feathers throughout.', '2008-03-06 16:20:22.000000', NULL, 1),
(4543741, 652740, 30982, '<td valign="top">I like the aspect of him coming out of the frame.  About my only nit is his teeth look like they''re overwhitened but that''s a very minor detail.</td>', 'I like the aspect of him coming out of the frame.  About my only nit is his teeth look like they''re overwhitened but that''s a very minor detail.', '2008-03-06 16:22:57.000000', NULL, 1),
(4543765, 653116, 811, '<td valign="top">I like the lonely, desolate, and cold feeling in this.  I do think it would feel more balanced, though, if the horizon didn''t cut the frame in half.  For this shot, a lot of negative space in the sky might be effective.</td>', 'I like the lonely, desolate, and cold feeling in this.  I do think it would feel more balanced, though, if the horizon didn''t cut the frame in half.  For this shot, a lot of negative space in the sky might be effective.', '2008-03-06 16:44:48.000000', NULL, 1),
(4543766, 652568, 811, '<td valign="top">I like the perspective and composition in this.  I truly hope you weren''t really that close to this animal (that can be dangerous).  It is nicely done and you will probably score well.  For me, though, I don''t like the HDRish look to the grasses.</td>', 'I like the perspective and composition in this.  I truly hope you weren''t really that close to this animal (that can be dangerous).  It is nicely done and you will probably score well.  For me, though, I don''t like the HDRish look to the grasses.', '2008-03-06 16:46:39.000000', NULL, 1),
(4543772, 652645, 811, '<td valign="top">I bet this would be really impressive as a huge print.  I like the colors and the "warm" feeling it has (not color warm, but temperature warm -- I''m tired of winter).</td>', 'I bet this would be really impressive as a huge print.  I like the colors and the "warm" feeling it has (not color warm, but temperature warm -- I''m tired of winter).', '2008-03-06 16:48:56.000000', NULL, 1),
(4543774, 652728, 811, '<td valign="top">Great clarity and exposure.</td>', 'Great clarity and exposure.', '2008-03-06 16:49:26.000000', NULL, 1),
(4543778, 649315, 811, '<td valign="top">The composition in this is really good.  I also like the contrast in the lighting.  However, it looks as if the focus is a bit off -- it is too focused to be soft focused and not focused enough to be sharp.  Definitely a concept to keep working on, though, I think.</td>', 'The composition in this is really good.  I also like the contrast in the lighting.  However, it looks as if the focus is a bit off -- it is too focused to be soft focused and not focused enough to be sharp.  Definitely a concept to keep working on, though, I think.', '2008-03-06 16:51:00.000000', NULL, 1),
(4543780, 652130, 811, '<td valign="top">I really, really like this one. . .</td>', 'I really, really like this one. . .', '2008-03-06 16:52:49.000000', NULL, 1),
(4543781, 652006, 811, '<td valign="top">wonderful view.  i like the colors, just not the almost cartoonish quality of them.  hdr?</td>', 'wonderful view.  i like the colors, just not the almost cartoonish quality of them.  hdr?', '2008-03-06 16:54:03.000000', NULL, 1),
(4543783, 652716, 811, '<td valign="top">I like the "massiveness" you have captured here.</td>', 'I like the "massiveness" you have captured here.', '2008-03-06 16:55:32.000000', NULL, 1),
(4543786, 651820, 811, '<td valign="top">great focus and detail in this.</td>', 'great focus and detail in this.', '2008-03-06 16:56:18.000000', NULL, 1),
(4543789, 649184, 811, '<td valign="top">At first glance, I thought it was a river going up the right side of the frame and could not, for the life of me figure out what those "bubbles" were.  Obviously, I am much relieved at realizing that is not water but "railing"</td>', 'At first glance, I thought it was a river going up the right side of the frame and could not, for the life of me figure out what those "bubbles" were.  Obviously, I am much relieved at realizing that is not water but "railing"', '2008-03-06 16:57:53.000000', NULL, 1),
(4543795, 652879, 811, '<td valign="top">I like the "environmental" nature of the portrait and the perspective you have chosen.  There''s something that I can''t quite put my finger on, though, that makes it feel just a bit out of focus.</td>', 'I like the "environmental" nature of the portrait and the perspective you have chosen.  There''s something that I can''t quite put my finger on, though, that makes it feel just a bit out of focus.', '2008-03-06 17:00:14.000000', NULL, 1),
(4543796, 652322, 811, '<td valign="top">very, very pretty.  great composition and colors.</td>', 'very, very pretty.  great composition and colors.', '2008-03-06 17:00:59.000000', NULL, 1),
(4543812, 646219, 811, '<td valign="top">that is cool</td>', 'that is cool', '2008-03-06 17:11:35.000000', NULL, 1),
(4543816, 649986, 811, '<td valign="top">Nicely done.  Good lighting, well-balanced composition.</td>', 'Nicely done.  Good lighting, well-balanced composition.', '2008-03-06 17:13:14.000000', NULL, 1),
(4543818, 642942, 811, '<td valign="top">I like the bright colors.</td>', 'I like the bright colors.', '2008-03-06 17:15:01.000000', NULL, 1),
(4543820, 653061, 811, '<td valign="top">To me, this is about as close to perfect as you can get in a photograph.  It is one of those that makes me wish I had taken it. . .</td>', 'To me, this is about as close to perfect as you can get in a photograph.  It is one of those that makes me wish I had taken it. . .', '2008-03-06 17:15:45.000000', NULL, 1),
(4543821, 652709, 811, '<td valign="top">That''s kinda freaky</td>', 'That''s kinda freaky', '2008-03-06 17:16:14.000000', NULL, 1),
