(4545014, 652872, 811, '<td valign="top">Great detail and focus.  Wonderfully done.</td>', 'Great detail and focus.  Wonderfully done.', '2008-03-07 09:34:27.000000', NULL, 1),
(4545045, 652784, 811, '<td valign="top">kinda matches my mood at this moment.  :)  very nice use of the light.  also i like the pole on the left.  it gives the feeling of being on the outside looking in and further isolating your subject from  everyone around.</td>', 'kinda matches my mood at this moment.  :)  very nice use of the light.  also i like the pole on the left.  it gives the feeling of being on the outside looking in and further isolating your subject from  everyone around.', '2008-03-07 09:39:42.000000', NULL, 1),
(4545053, 652600, 811, '<td valign="top">I like composition, but I don''t care too much for the effect that post processing (I assume) had on it.</td>', 'I like composition, but I don''t care too much for the effect that post processing (I assume) had on it.', '2008-03-07 09:41:43.000000', NULL, 1),
(4545061, 652868, 30982, '<td valign="top">I like how the tree behind initially looks like an explosion, offseting the boxing match in the foreground.  Lovely light, great action shot.  Back to bump.  Somehow it''s almost surrealistic and I like it better each time I visit it.</td>', 'I like how the tree behind initially looks like an explosion, offseting the boxing match in the foreground.  Lovely light, great action shot.  Back to bump.  Somehow it''s almost surrealistic and I like it better each time I visit it.', '2008-03-07 09:43:09.000000', NULL, 1),
(4545063, 653106, 30982, '<td valign="top">Excellent detail for black!</td>', 'Excellent detail for black!', '2008-03-07 09:43:14.000000', NULL, 1),
(4545068, 653110, 67258, '<td valign="top">Outstanding natural history photograph. Certainly depicts the power of these birds.</td>', 'Outstanding natural history photograph. Certainly depicts the power of these birds.', '2008-03-07 09:44:30.000000', NULL, 1),
(4545090, 652896, 67258, '<td valign="top">For me the processing has removed this image from the category of photography to digital art, and seems to be a case of manipulation for the sake of it.  I would be interested to see the original photo, and to read your notes on what your aim was with the processing.</td>', 'For me the processing has removed this image from the category of photography to digital art, and seems to be a case of manipulation for the sake of it.  I would be interested to see the original photo, and to read your notes on what your aim was with the processing.', '2008-03-07 09:50:27.000000', NULL, 1),
(4545104, 652982, 811, '<td valign="top">I like this.  I like the "muted" colors and the perspective.</td>', 'I like this.  I like the "muted" colors and the perspective.', '2008-03-07 09:58:38.000000', NULL, 1),
(4545109, 652714, 811, '<td valign="top">good capture, and i like the colors.  there''s something, though, that I can''t quite put my finger on -- overuse of noise reduction, *maybe*</td>', 'good capture, and i like the colors.  there''s something, though, that I can''t quite put my finger on -- overuse of noise reduction, *maybe*', '2008-03-07 09:59:41.000000', NULL, 1),
