INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4545712, 650119, 39850, '<td valign="top">7 - Nice pose and expressions captured.</td>', '7 - Nice pose and expressions captured.', '2008-03-07 13:40:01.000000', NULL, 1),
(4545714, 651815, 65234, '<td valign="top">This seems like it should be an illustration in a children''s book.  Stark, simple colors and shapes.  I love the way you framed the little sun.  Nice work.</td>', 'This seems like it should be an illustration in a children''s book.  Stark, simple colors and shapes.  I love the way you framed the little sun.  Nice work.', '2008-03-07 13:40:16.000000', NULL, 1),
(4545715, 652992, 68546, '<td valign="top">Excellent crop and amazing eyes! The flash has produced an unattractive shadow position and is angled slightly upwards which is unnatural way for it to go. If this is on camera (or hotshoe) flash then you may have been better turning the camera the other way around and so the flash in on camera right, this would have given a better lighting on the face I think. Just my opinion though and this is an excellent portrait as it is</td>', 'Excellent crop and amazing eyes! The flash has produced an unattractive shadow position and is angled slightly upwards which is unnatural way for it to go. If this is on camera (or hotshoe) flash then you may have been better turning the camera the other way around and so the flash in on camera right, this would have given a better lighting on the face I think. Just my opinion though and this is an excellent portrait as it is', '2008-03-07 13:40:23.000000', NULL, 1),
(4545716, 641578, 68546, '<td valign="top">amazingly sharp! Like the warm feel to it as well</td>', 'amazingly sharp! Like the warm feel to it as well', '2008-03-07 13:40:50.000000', NULL, 1),
(4545722, 653092, 68546, '<td valign="top">The soft focus (or neat image?) processing fits the dreamy feel of the shot but it''s lacking something that makes it stand out.</td>', 'The soft focus (or neat image?) processing fits the dreamy feel of the shot but it''s lacking something that makes it stand out.', '2008-03-07 13:42:26.000000', NULL, 1),
(4545723, 652273, 65234, '<td valign="top">Lovely fluffy clouds, great colors in the ocean, and perfect placement of the subject in the frame.  The idea of home being nearby is reinforced by the little bit of red roofs and white buildings almost out of sight.</td>', 'Lovely fluffy clouds, great colors in the ocean, and perfect placement of the subject in the frame.  The idea of home being nearby is reinforced by the little bit of red roofs and white buildings almost out of sight.', '2008-03-07 13:42:45.000000', NULL, 1),
(4545731, 653123, 65234, '<td valign="top">Your cow looks bullish.  Nice reflection.</td>', 'Your cow looks bullish.  Nice reflection.', '2008-03-07 13:44:39.000000', NULL, 1),
(4545732, 652868, 74559, '<td valign="top">Amazing capture! I didn''t realize bunnies boxed :-)</td>', 'Amazing capture! I didn''t realize bunnies boxed :-)', '2008-03-07 13:44:43.000000', NULL, 1),
(4545733, 650163, 68546, '<td valign="top">Nice HDR, a little flat though as there is no feeling of depth between the forground on the right and the background on the left. I can see the shape but it''s not a 3 dimensional feeling</td>', 'Nice HDR, a little flat though as there is no feeling of depth between the forground on the right and the background on the left. I can see the shape but it''s not a 3 dimensional feeling', '2008-03-07 13:44:51.000000', NULL, 1),
(4545734, 649184, 39850, '<td valign="top">7 - Nice perspective, dont mind the tilt (although wonder whether this would be stronger straightened), like the top of the bridge, but what makes this image is the railing that you''ve captured, allowing the viewer to ''feel'' the city too - just wish the fore focus was stronger.</td>', '7 - Nice perspective, dont mind the tilt (although wonder whether this would be stronger straightened), like the top of the bridge, but what makes this image is the railing that you''ve captured, allowing the viewer to ''feel'' the city too - just wish the fore focus was stronger.', '2008-03-07 13:44:52.000000', NULL, 1),
(4545736, 648613, 65234, '<td valign="top">Nice shapes and textures.</td>', 'Nice shapes and textures.', '2008-03-07 13:45:21.000000', NULL, 1),
(4545738, 647592, 65234, '<td valign="top">Looks like a fascinating place to explore.</td>', 'Looks like a fascinating place to explore.', '2008-03-07 13:45:44.000000', NULL, 1),
(4545739, 652572, 68546, '<td valign="top">Excellent portrait, love the DOF and smooth brokeh</td>', 'Excellent portrait, love the DOF and smooth brokeh', '2008-03-07 13:46:12.000000', NULL, 1),
(4545741, 651439, 39850, '<td valign="top">8 - Nice portrait, like the backlighting and the crop, wonder whether the image would be a little stronger without the dark vignetting, especially at the top, but probably intentional.</td>', '8 - Nice portrait, like the backlighting and the crop, wonder whether the image would be a little stronger without the dark vignetting, especially at the top, but probably intentional.', '2008-03-07 13:46:33.000000', NULL, 1),
(4545743, 647599, 65234, '<td valign="top">Okra: the hairy, slimy vegetable!  But it has nice shapes and color.</td>', 'Okra: the hairy, slimy vegetable!  But it has nice shapes and color.', '2008-03-07 13:46:59.000000', NULL, 1),
(4545744, 653072, 68546, '<td valign="top">excellent portrait, great expression, crop, and tones.</td>', 'excellent portrait, great expression, crop, and tones.', '2008-03-07 13:47:25.000000', NULL, 1),
(4545746, 643683, 68546, '<td valign="top">Great composition and colour. Nice eye contact but the eyes are a little on the dark side.</td>', 'Great composition and colour. Nice eye contact but the eyes are a little on the dark side.', '2008-03-07 13:48:02.000000', NULL, 1),
(4545748, 652894, 65234, '<td valign="top">Took me a sec to see the raven.  Very cool effect.</td>', 'Took me a sec to see the raven.  Very cool effect.', '2008-03-07 13:48:24.000000', NULL, 1),
(4545750, 651380, 39850, '<td valign="top">Nice scene, not sure on the square crop - wonder about a vertical, especially with those lines in the snow at the fore.</td>', 'Nice scene, not sure on the square crop - wonder about a vertical, especially with those lines in the snow at the fore.', '2008-03-07 13:48:47.000000', NULL, 1),
(4545753, 651615, 74559, '<td valign="top">Beautiful colors, very dramatic skies! Very nice line of the structure leading to the sunset.</td>', 'Beautiful colors, very dramatic skies! Very nice line of the structure leading to the sunset.', '2008-03-07 13:49:17.000000', NULL, 1),
(4545754, 652345, 68546, '<td valign="top">really nice shot, great detail on the mountains and the soft water is really good. Needs some foreground interest to make it more balanced.</td>', 'really nice shot, great detail on the mountains and the soft water is really good. Needs some foreground interest to make it more balanced.', '2008-03-07 13:49:20.000000', NULL, 1),
(4545756, 642667, 65234, '<td valign="top">This reminds me of a Dr. Suess landscape.  Maybe the Grinch?  Nice job on the exposure.</td>', 'This reminds me of a Dr. Suess landscape.  Maybe the Grinch?  Nice job on the exposure.', '2008-03-07 13:49:39.000000', NULL, 1),
(4545759, 652699, 39850, '<td valign="top">7 - Nice scene and lighting.  Overall seems a little off-balanced - maybe cropping much tighter on the left, not sure.</td>', '7 - Nice scene and lighting.  Overall seems a little off-balanced - maybe cropping much tighter on the left, not sure.', '2008-03-07 13:50:40.000000', NULL, 1),
(4545760, 652108, 68546, '<td valign="top">Great composition, colour and setting. Needs more exposure in the blacks though as there is no details in them at all and the sea is underexposed.</td>', 'Great composition, colour and setting. Needs more exposure in the blacks though as there is no details in them at all and the sea is underexposed.', '2008-03-07 13:50:55.000000', NULL, 1),
(4545761, 649556, 74559, '<td valign="top">I love everything about this -- the location, the amazing sky and reflection, the lens distortion... excellent processing to get all of the cloud details!</td>', 'I love everything about this -- the location, the amazing sky and reflection, the lens distortion... excellent processing to get all of the cloud details!', '2008-03-07 13:51:14.000000', NULL, 1),
(4545763, 652698, 68546, '<td valign="top">Nice crop, expression, and DOF but the hair is a definite distraction</td>', 'Nice crop, expression, and DOF but the hair is a definite distraction', '2008-03-07 13:51:32.000000', NULL, 1),
(4545764, 652119, 65234, '<td valign="top">Oh, pretty {{{purples}}}  Can''t say that I''ve ever seen the DC sky quite that color, but I like it.</td>', 'Oh, pretty {{{purples}}}  Can''t say that I''ve ever seen the DC sky quite that color, but I like it.', '2008-03-07 13:51:36.000000', NULL, 1),
(4545768, 648704, 68546, '<td valign="top">A little over processed for my taste. A little too heavy handed with the noise reduction steps. Nice portrait though</td>', 'A little over processed for my taste. A little too heavy handed with the noise reduction steps. Nice portrait though', '2008-03-07 13:52:26.000000', NULL, 1),
