(4545780, 652800, 65234, '<td valign="top">Lovely lighting.  I love that the little sapling is safe and snug and reaching up to the light.</td>', 'Lovely lighting.  I love that the little sapling is safe and snug and reaching up to the light.', '2008-03-07 13:54:40.000000', NULL, 1),
(4545782, 641407, 68546, '<td valign="top">this is just plain weird!! like the composition, processing, crop. Have no idea what it''s representing though? Still a 7 for being interesting!</td>', 'this is just plain weird!! like the composition, processing, crop. Have no idea what it''s representing though? Still a 7 for being interesting!', '2008-03-07 13:55:04.000000', NULL, 1),
