(4546604, 641578, 23430, '<td valign="top">Beautifully sharp. I like where your bee is positioned and angled in the frame. Great surrounding colour. All round great shot.</td>', 'Beautifully sharp. I like where your bee is positioned and angled in the frame. Great surrounding colour. All round great shot.', '2008-03-07 20:05:37.000000', NULL, 1),
(4546605, 652568, 23430, '<td valign="top">Totally awesome shot. The combination of the colours, the wide angle, the light and of course your brilliant subject does it for me. Love the composition too.</td>', 'Totally awesome shot. The combination of the colours, the wide angle, the light and of course your brilliant subject does it for me. Love the composition too.', '2008-03-07 20:05:42.000000', NULL, 1),
(4546607, 648508, 69246, '<td valign="top">At first, I think....a bit dark....then I look, really look, and I get such a warm feeling and I think....perfect.</td>', 'At first, I think....a bit dark....then I look, really look, and I get such a warm feeling and I think....perfect.', '2008-03-07 20:07:17.000000', NULL, 1),
(4546608, 646649, 69246, '<td valign="top">Highlights are a big pushed and shutter speed seems a bit lot for stop action.</td>', 'Highlights are a big pushed and shutter speed seems a bit lot for stop action.', '2008-03-07 20:07:58.000000', NULL, 1),
(4546609, 651539, 69246, '<td valign="top">Good action shot, but very tough to take. My guess is that this wasn''t taken with an SLR. Maybe I''m wrong. But control on shutter speed and faster ISO would help this a lot.</td>', 'Good action shot, but very tough to take. My guess is that this wasn''t taken with an SLR. Maybe I''m wrong. But control on shutter speed and faster ISO would help this a lot.', '2008-03-07 20:09:57.000000', NULL, 1),
(4546615, 645837, 1024, '<td valign="top">This is excellent!  The use of blur to convey motion is very well done.</td>', 'This is excellent!  The use of blur to convey motion is very well done.', '2008-03-07 20:16:05.000000', NULL, 1),
(4546617, 652336, 1024, '<td valign="top">And they just go on forever......</td>', 'And they just go on forever......', '2008-03-07 20:16:28.000000', NULL, 1),
(4546618, 649537, 1024, '<td valign="top">Wonderful macro.  My cat would never sit still for this.</td>', 'Wonderful macro.  My cat would never sit still for this.', '2008-03-07 20:16:57.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4546619, 649509, 1024, '<td valign="top">Whoa, when this first opened I jumped just a little bit.  You get an extra point for that.</td>', 'Whoa, when this first opened I jumped just a little bit.  You get an extra point for that.', '2008-03-07 20:17:37.000000', NULL, 1),
(4546623, 645616, 1024, '<td valign="top">There is something other worldly about this. like a light from the under world.  I had to look for a minute to figure it out.</td>', 'There is something other worldly about this. like a light from the under world.  I had to look for a minute to figure it out.', '2008-03-07 20:18:43.000000', NULL, 1),
(4546625, 653113, 23002, '<td valign="top">Ok, it looks like a plant that is rooting in a glass of water, and I can see a water drop on the outside of the glass.<br/> <br/>I like the macro type close up of the plant growth, however I think that the overall brightness on the white parts of the plant and the glass itself detracts from a great concept.  I might not have included the sides of the glass either.<br/> <br/>Bottom line is that I like the concept, I like the plant, but it appears a bit overexposed. :)</td>', 'Ok, it looks like a plant that is rooting in a glass of water, and I can see a water drop on the outside of the glass. I like the macro type close up of the plant growth, however I think that the overall brightness on the white parts of the plant and the glass itself detracts from a great concept.  I might not have included the sides of the glass either. Bottom line is that I like the concept, I like the plant, but it appears a bit overexposed. :)', '2008-03-07 20:19:52.000000', NULL, 1),
(4546628, 648343, 23002, '<td valign="top">beautiful work.  Love the great DOF.</td>', 'beautiful work.  Love the great DOF.', '2008-03-07 20:20:27.000000', NULL, 1),
(4546630, 650119, 23002, '<td valign="top">Very powerful.  I love the great colours in the background that help set off the primarily black and white subjects.</td>', 'Very powerful.  I love the great colours in the background that help set off the primarily black and white subjects.', '2008-03-07 20:21:29.000000', NULL, 1),
(4546635, 653070, 23002, '<td valign="top">Love it.  I like how the canal takes you through the image and there is blue sky at the end.  The threatening grey clouds give a sense of excitment to the scene.  I would like it more without the car on the left, but I am sure you were in no  position to ask folks to move their vehicles! LOL</td>', 'Love it.  I like how the canal takes you through the image and there is blue sky at the end.  The threatening grey clouds give a sense of excitment to the scene.  I would like it more without the car on the left, but I am sure you were in no  position to ask folks to move their vehicles! LOL', '2008-03-07 20:22:57.000000', NULL, 1),
(4546642, 653022, 23002, '<td valign="top">Very powerful!  I love the abandoned building which is very well lit and exposed (so that folks hopefully cannot bitch about the on purpose overexposure of the human subject).  The human figure bathed in bright light, in that pose certainly gets your point across.  Into the great white light...<br/> <br/>This is a 10 and a fave. :)<br/> <br/>ETA:  I nominated this image for an OOBIE award from Team Suck. :)<br/><br/><i>Message edited by author 2008-03-08 12:52:18.</i></td>', 'Very powerful!  I love the abandoned building which is very well lit and exposed (so that folks hopefully cannot bitch about the on purpose overexposure of the human subject).  The human figure bathed in bright light, in that pose certainly gets your point across.  Into the great white light... This is a 10 and a fave. :) ETA:  I nominated this image for an OOBIE award from Team Suck. :)', '2008-03-07 20:24:54.000000', '2008-03-08 12:52:18.000000', 1),
(4546644, 652907, 23002, '<td valign="top">this is a great view of some balconies.  Nicely seen.</td>', 'this is a great view of some balconies.  Nicely seen.', '2008-03-07 20:25:30.000000', NULL, 1),
(4546648, 649643, 23002, '<td valign="top">A portable scud missle launcher? LOL.<br/> <br/>Nicely seen and I like the sepia toning.</td>', 'A portable scud missle launcher? LOL. Nicely seen and I like the sepia toning.', '2008-03-07 20:26:17.000000', NULL, 1),
(4546653, 652437, 23002, '<td valign="top">I am sure that folks are all over you about the tilted horizon, but I am sure you left it like that for a reason.  I love the  silhouettes.</td>', 'I am sure that folks are all over you about the tilted horizon, but I am sure you left it like that for a reason.  I love the  silhouettes.', '2008-03-07 20:28:23.000000', NULL, 1),
(4546655, 653073, 23002, '<td valign="top">I love that the bike is leaning against the "parking in rear" sign.</td>', 'I love that the bike is leaning against the "parking in rear" sign.', '2008-03-07 20:29:10.000000', NULL, 1),
(4546659, 650070, 23002, '<td valign="top">Nice portrait, however if her face was not actually leaning so hard on her forearm it owuld help the right side of the model''s face appear more natural and not scrunched up.  Overall I like it.</td>', 'Nice portrait, however if her face was not actually leaning so hard on her forearm it owuld help the right side of the model''s face appear more natural and not scrunched up.  Overall I like it.', '2008-03-07 20:30:27.000000', NULL, 1),
(4546663, 651564, 23002, '<td valign="top">You had an interesting choice to make here, to have the horizon tilted one way or the waves disecting the image the opposite way.  It appears you split the difference which is fine with me. :)<br/> <br/>Love the silhouette.</td>', 'You had an interesting choice to make here, to have the horizon tilted one way or the waves disecting the image the opposite way.  It appears you split the difference which is fine with me. :) Love the silhouette.', '2008-03-07 20:31:54.000000', NULL, 1),
(4546667, 650756, 23002, '<td valign="top">I tend to think that this bird was not photographed in the wild.  It is a great shot, but please do not mislead the viewers into thinking that this is taken of a wild bird.</td>', 'I tend to think that this bird was not photographed in the wild.  It is a great shot, but please do not mislead the viewers into thinking that this is taken of a wild bird.', '2008-03-07 20:33:30.000000', NULL, 1),
(4546670, 651407, 23002, '<td valign="top">I normally do not like overly processed images, but this one is an exception.  It has a nice painterly effect.</td>', 'I normally do not like overly processed images, but this one is an exception.  It has a nice painterly effect.', '2008-03-07 20:34:42.000000', NULL, 1),
(4546673, 645335, 23002, '<td valign="top">Another great captive bird image.</td>', 'Another great captive bird image.', '2008-03-07 20:35:38.000000', NULL, 1),
