(4546790, 652897, 86447, '<td valign="top">Lovely.  Sharp and artistic.  One of only three 10s for me this time.</td>', 'Lovely.  Sharp and artistic.  One of only three 10s for me this time.', '2008-03-07 21:22:10.000000', NULL, 1),
(4546792, 645830, 86447, '<td valign="top">If I could see the other eye this would be a perfect ten. Well... and the bows should not clash in color.   Well done!</td>', 'If I could see the other eye this would be a perfect ten. Well... and the bows should not clash in color.   Well done!', '2008-03-07 21:22:25.000000', NULL, 1),
