INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4547286, 650756, 39830, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by basssman7:</b></div><hr/><i> I tend to think that this bird was not photographed in the wild.  It is a great shot, but please do not mislead the viewers into thinking that this is taken of a wild bird. </i></td></tr></table> <br/> <br/>Pfft... The bird is now in captivity, but you are mistaken if you think it is by any measure tame.</td>', 'Originally posted by basssman7: I tend to think that this bird was not photographed in the wild.  It is a great shot, but please do not mislead the viewers into thinking that this is taken of a wild bird.   Pfft... The bird is now in captivity, but you are mistaken if you think it is by any measure tame.', '2008-03-08 01:50:45.000000', NULL, 0),
(4547287, 651395, 30982, '<td valign="top">You got a 9 from me - I suppose I should have left a comment, huh?  A very warm, real portrait.  Just has a nice "feels good" feel to it if that makes sense.</td>', 'You got a 9 from me - I suppose I should have left a comment, huh?  A very warm, real portrait.  Just has a nice "feels good" feel to it if that makes sense.', '2008-03-08 01:52:30.000000', NULL, 0),
(4547289, 653123, 30982, '<td valign="top">Just freakin'' too much fun!  Did I say that already?  Well, it is!  GREAT shot.  After looking over the entries one last time, I thought "I wonder if this is Colleen''s"?  Also thought it might be Goodman''s.</td>', 'Just freakin'' too much fun!  Did I say that already?  Well, it is!  GREAT shot.  After looking over the entries one last time, I thought "I wonder if this is Colleen''s"?  Also thought it might be Goodman''s.', '2008-03-08 01:54:03.000000', NULL, 0),
