(4547477, 652897, 18450, '<td valign="top">Exquisite shot! Congrats on your well deserved top 5 Irene!!!!</td>', 'Exquisite shot! Congrats on your well deserved top 5 Irene!!!!', '2008-03-08 04:33:11.000000', NULL, 0),
