(4547786, 652992, 51538, '<td valign="top">Came back to appreciate.  Gave an 8 in the voting and still think this is an exceptional image.  Nice work.</td>', 'Came back to appreciate.  Gave an 8 in the voting and still think this is an exceptional image.  Nice work.', '2008-03-08 08:34:30.000000', NULL, 0),
(4547788, 653073, 55838, '<td valign="top">Underrated IMO but DPCers don''t always reward the good eye for a real world feeling shot.  :(  I do though - because I really admire that ability.  Nicely done!</td>', 'Underrated IMO but DPCers don''t always reward the good eye for a real world feeling shot.  :(  I do though - because I really admire that ability.  Nicely done!', '2008-03-08 08:34:41.000000', NULL, 0),
(4547790, 648149, 55838, '<td valign="top">Congratualtions on your new personal best!!  And in a Free Study no less!  Nicely done.  I second Brad''s comments.</td>', 'Congratualtions on your new personal best!!  And in a Free Study no less!  Nicely done.  I second Brad''s comments.', '2008-03-08 08:37:07.000000', NULL, 0),
(4547792, 652888, 51538, '<td valign="top">Nice to read your notes.  Came back to appreciate this view of the great outdoors.</td>', 'Nice to read your notes.  Came back to appreciate this view of the great outdoors.', '2008-03-08 08:40:08.000000', NULL, 0),
(4547794, 645960, 51538, '<td valign="top">I''m inclined to like black and white renditions of this subject with plenty of shadows and motion blur.  But yours is a good reporterly shot.</td>', 'I''m inclined to like black and white renditions of this subject with plenty of shadows and motion blur.  But yours is a good reporterly shot.', '2008-03-08 08:41:23.000000', NULL, 0),
