(4548138, 652011, 29156, '<td valign="top">great b&amp;w tones</td>', 'great b&w tones', '2008-03-08 11:45:31.000000', NULL, 0),
(4548141, 645830, 29156, '<td valign="top">cute</td>', 'cute', '2008-03-08 11:46:18.000000', NULL, 0),
