(4548145, 652543, 29156, '<td valign="top">nice light and color process</td>', 'nice light and color process', '2008-03-08 11:48:12.000000', NULL, 0),
(4548151, 653041, 29156, '<td valign="top">cool work, great in b&amp;w</td>', 'cool work, great in b&w', '2008-03-08 11:49:55.000000', NULL, 0),
(4548155, 653115, 81301, '<td valign="top">congrats. amazing PS work.</td>', 'congrats. amazing PS work.', '2008-03-08 11:51:47.000000', NULL, 0),
(4548163, 653080, 9462, '<td valign="top">Ooh, a posthumous yellow! This was one of my favorites of the challenge.</td>', 'Ooh, a posthumous yellow! This was one of my favorites of the challenge.', '2008-03-08 11:55:04.000000', NULL, 0),
(4548164, 652965, 30861, '<td valign="top">Boy, you got hammered. Stoopid voters... 7.5 average for commenters, 4.2 average overall... I think this is way cool, myself.</td>', 'Boy, you got hammered. Stoopid voters... 7.5 average for commenters, 4.2 average overall... I think this is way cool, myself.', '2008-03-08 11:55:25.000000', NULL, 0),
(4548169, 648508, 30861, '<td valign="top">Hey, nice work, nice score! WTG Juliet!</td>', 'Hey, nice work, nice score! WTG Juliet!', '2008-03-08 11:56:52.000000', NULL, 0),
(4548178, 652800, 53094, '<td valign="top">Your photographs are wonderful, and this one is no exception.  The color, lighting, everything seems just right.  With 455 entries in a free study, I think 19th is exceptional.  Ha, I''ll trade you...my PERFECT duck photo finished 241st!</td>', 'Your photographs are wonderful, and this one is no exception.  The color, lighting, everything seems just right.  With 455 entries in a free study, I think 19th is exceptional.  Ha, I''ll trade you...my PERFECT duck photo finished 241st!', '2008-03-08 12:00:28.000000', NULL, 0),
(4548190, 652992, 30861, '<td valign="top">Extraordinary! Extremely well done. Scored about as well as could be expected, but really deserves more. Fine work :-)</td>', 'Extraordinary! Extremely well done. Scored about as well as could be expected, but really deserves more. Fine work :-)', '2008-03-08 12:04:59.000000', NULL, 0),
(4548191, 653115, 69668, '<td valign="top">This was my only 10 in the entire group.  This is just beautiful.  I knew it would be at the top when I opened up the results.  It was the very first shot that I voted on and nothing could compare after seeing this.  WOW</td>', 'This was my only 10 in the entire group.  This is just beautiful.  I knew it would be at the top when I opened up the results.  It was the very first shot that I voted on and nothing could compare after seeing this.  WOW', '2008-03-08 12:05:06.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4548200, 649556, 76335, '<td valign="top">A little over the top for me, but WOW! all the same. Nice work and nice finish...</td>', 'A little over the top for me, but WOW! all the same. Nice work and nice finish...', '2008-03-08 12:09:05.000000', NULL, 0),
(4548202, 652869, 9462, '<td valign="top">This photo is so far beyond the average DPC viewer''s ability to appreciate, so sorely underrated. I was one of your 10''s and would''ve chosen this for blue, easily.</td>', 'This photo is so far beyond the average DPC viewer''s ability to appreciate, so sorely underrated. I was one of your 10''s and would''ve chosen this for blue, easily.', '2008-03-08 12:11:07.000000', NULL, 0),
(4548207, 648777, 66952, '<td valign="top">Wow, Owen! Yes! Perfect shot.</td>', 'Wow, Owen! Yes! Perfect shot.', '2008-03-08 12:12:48.000000', NULL, 0),
(4548220, 652993, 44877, '<td valign="top">I absolutely loved this during voting. Not surprised (though disappointed) that it didn''t score higher, since it''s not very dpc-esque. However - HUGE congrats on the Posthumous blue!! In my mind, that''s a real prize. <br/> <br/>This photo is completely inspired and so beautiful. Thanks for sharing it with us.</td>', 'I absolutely loved this during voting. Not surprised (though disappointed) that it didn''t score higher, since it''s not very dpc-esque. However - HUGE congrats on the Posthumous blue!! In my mind, that''s a real prize.  This photo is completely inspired and so beautiful. Thanks for sharing it with us.', '2008-03-08 12:18:37.000000', NULL, 0),
(4548224, 649537, 29011, '<td valign="top">Wonderful capture. This is not your ordinary cat pic. I really like this very unique perspective. The point of focus and DOF is perfect. The choice to post in b/w wasn''t a mistake I reckon, it looks great. This would be great as part of series on a closeup look at cats.</td>', 'Wonderful capture. This is not your ordinary cat pic. I really like this very unique perspective. The point of focus and DOF is perfect. The choice to post in b/w wasn''t a mistake I reckon, it looks great. This would be great as part of series on a closeup look at cats.', '2008-03-08 12:20:41.000000', NULL, 0),
(4548225, 652275, 44877, '<td valign="top">Yay for the yella posthumous - that''s the least this deserves. Wowee.</td>', 'Yay for the yella posthumous - that''s the least this deserves. Wowee.', '2008-03-08 12:20:59.000000', NULL, 0),
(4548227, 649643, 9462, '<td valign="top">I quite liked this one... but I knew it wouldn''t fair well with the DPC crowd.<br/>The composition is fantastic, good catch.</td>', 'I quite liked this one... but I knew it wouldn''t fair well with the DPC crowd.The composition is fantastic, good catch.', '2008-03-08 12:21:58.000000', NULL, 0),
(4548230, 652965, 44877, '<td valign="top">Loved it during voting - and still do. Good that you got acknowledgment via the Posthumous Yellow. It''s very beautiful and very inspired.</td>', 'Loved it during voting - and still do. Good that you got acknowledgment via the Posthumous Yellow. It''s very beautiful and very inspired.', '2008-03-08 12:22:32.000000', NULL, 0),
(4548235, 647023, 44877, '<td valign="top">Can''t believe this didn''t score higher! It''s just fantastic.</td>', 'Can''t believe this didn''t score higher! It''s just fantastic.', '2008-03-08 12:23:59.000000', NULL, 0),
(4548242, 652799, 44877, '<td valign="top">Love this photo! I didn''t comment during voting due to time constraints, but I''m going back and commenting on some now - such as this. Wonderfully seen and processed. Absolutely adore the moment you captured. Hope to see more from you along these lines.</td>', 'Love this photo! I didn''t comment during voting due to time constraints, but I''m going back and commenting on some now - such as this. Wonderfully seen and processed. Absolutely adore the moment you captured. Hope to see more from you along these lines.', '2008-03-08 12:27:04.000000', NULL, 0),
(4548248, 652992, 44877, '<td valign="top">In every Free Study there are mediocre portraits - lots of them. I was so delighted to see this most inspired and vivid portrait, which really stands way out from all the others. It got high marks from me, and I''m happy to see it mentioned in the Posthumous thread. Beautiful work.</td>', 'In every Free Study there are mediocre portraits - lots of them. I was so delighted to see this most inspired and vivid portrait, which really stands way out from all the others. It got high marks from me, and I''m happy to see it mentioned in the Posthumous thread. Beautiful work.', '2008-03-08 12:29:44.000000', NULL, 0),
(4548262, 652479, 30982, '<td valign="top">I''m very much surprised by the score - I love the quietness and softness of this.  Nice work with PS, and I do like that a faint tint of the greenish color remains on the boats to set them apart just a bit.</td>', 'I''m very much surprised by the score - I love the quietness and softness of this.  Nice work with PS, and I do like that a faint tint of the greenish color remains on the boats to set them apart just a bit.', '2008-03-08 12:37:03.000000', NULL, 0),
(4548265, 652869, 30982, '<td valign="top">My kind of shot.  Windows and reflections fascinate me.  This one has a desperate loneliness to me (or it could just be my mood - who knows.)  I see a chair at the bottom, no one in it; the guy up the steps alone.  Kinda sad.</td>', 'My kind of shot.  Windows and reflections fascinate me.  This one has a desperate loneliness to me (or it could just be my mood - who knows.)  I see a chair at the bottom, no one in it; the guy up the steps alone.  Kinda sad.', '2008-03-08 12:38:36.000000', NULL, 0),
(4548268, 652119, 23002, '<td valign="top">gorgeous!  I love the reflection of the clouds.<br/> <br/>You have the blueprint for these amazing waterscapes! (can I borrow the blueprint sometime??)</td>', 'gorgeous!  I love the reflection of the clouds. You have the blueprint for these amazing waterscapes! (can I borrow the blueprint sometime??)', '2008-03-08 12:39:32.000000', NULL, 0),
(4548273, 652868, 9462, '<td valign="top">Such dedication! It really was worth the effort!</td>', 'Such dedication! It really was worth the effort!', '2008-03-08 12:42:45.000000', NULL, 0),
(4548274, 652868, 23002, '<td valign="top">Sara, this is an amazing shot!  First off I love the frost, gives a nice sense of morning to add a timeline to the production.  I love the way you positioned them in the frame, it balances out the big tree in the background.  I salute you for spending the time it took to capture this wonderful ritual of nature.  This one is a fav. :)</td>', 'Sara, this is an amazing shot!  First off I love the frost, gives a nice sense of morning to add a timeline to the production.  I love the way you positioned them in the frame, it balances out the big tree in the background.  I salute you for spending the time it took to capture this wonderful ritual of nature.  This one is a fav. :)', '2008-03-08 12:42:59.000000', NULL, 0),
(4548279, 652333, 30982, '<td valign="top">How nice to have spring where you are!  Love the bee - it''s what makes this shot.  And the lavender color is perfect against the blue of the sky.  Well composed and presented.</td>', 'How nice to have spring where you are!  Love the bee - it''s what makes this shot.  And the lavender color is perfect against the blue of the sky.  Well composed and presented.', '2008-03-08 12:45:33.000000', NULL, 0),
(4548284, 650095, 30982, '<td valign="top">What an unreal place!  Love the alternate as well.  Will wander through your portfolio of New Zealand here shortly.</td>', 'What an unreal place!  Love the alternate as well.  Will wander through your portfolio of New Zealand here shortly.', '2008-03-08 12:47:33.000000', NULL, 0),
(4548288, 653116, 30982, '<td valign="top">A different kind of shot from you.  Very pastoral.  :-)</td>', 'A different kind of shot from you.  Very pastoral.  :-)', '2008-03-08 12:50:12.000000', NULL, 0),
(4548290, 652119, 30982, '<td valign="top">Lovely shot and a lovely score to go with it.</td>', 'Lovely shot and a lovely score to go with it.', '2008-03-08 12:51:18.000000', NULL, 0),
(4548294, 653016, 30982, '<td valign="top">His expression is just perfect.  He''s so intent and in tune with what he''s doing - lovely to see.</td>', 'His expression is just perfect.  He''s so intent and in tune with what he''s doing - lovely to see.', '2008-03-08 12:53:22.000000', NULL, 0),
(4548298, 653109, 30982, '<td valign="top">This reminds me of my first entry here at DPC.  :-)  I really like the shot a lot and very much appreciate that you converted to B&amp;W.  Those newer windmills look like aliens; the older one more comforting and familiar - and holding its ground, too.</td>', 'This reminds me of my first entry here at DPC.  :-)  I really like the shot a lot and very much appreciate that you converted to B&W.  Those newer windmills look like aliens; the older one more comforting and familiar - and holding its ground, too.', '2008-03-08 12:55:00.000000', NULL, 0),
(4548302, 644714, 30982, '<td valign="top">Very crisp, very clean - excellent detail!  I like the little catchlight in the eye, too.</td>', 'Very crisp, very clean - excellent detail!  I like the little catchlight in the eye, too.', '2008-03-08 12:56:02.000000', NULL, 0),
(4548303, 652130, 30982, '<td valign="top">One of my top three in this challenge.  ''Grats on kicking over the 6 line with this, too!</td>', 'One of my top three in this challenge.  ''Grats on kicking over the 6 line with this, too!', '2008-03-08 12:57:15.000000', NULL, 0),
(4548308, 652565, 30982, '<td valign="top">Grace, kindness, and a lovely gentleness radiate from this.  I''m glad you left it as it was, too.  (Border is fine, by the way.)</td>', 'Grace, kindness, and a lovely gentleness radiate from this.  I''m glad you left it as it was, too.  (Border is fine, by the way.)', '2008-03-08 12:59:42.000000', NULL, 0),
(4548311, 650398, 30982, '<td valign="top">Kinda like a three dimensional painting - very cool!</td>', 'Kinda like a three dimensional painting - very cool!', '2008-03-08 13:00:51.000000', NULL, 0),
(4548316, 652994, 30982, '<td valign="top">I think I commented on this one in your portfolio, didn''t I?  If not, I meant to.  I love the juxtaposition of the live couple with the photograph behind them.</td>', 'I think I commented on this one in your portfolio, didn''t I?  If not, I meant to.  I love the juxtaposition of the live couple with the photograph behind them.', '2008-03-08 13:02:18.000000', NULL, 0),
(4548318, 653136, 67258, '<td valign="top">Hamish, good on you for taking all the comments in the spirit in which they were intended.  It is good to experiment with new ideas and techniques - sometimes the results work, sometimes not, but experimentation will ultimately make you a better at both photography and post-processing (I really should take some of my own medicine....).  All that said, you have some wonderful photos in your portfolio; Pensive is gorgeous!</td>', 'Hamish, good on you for taking all the comments in the spirit in which they were intended.  It is good to experiment with new ideas and techniques - sometimes the results work, sometimes not, but experimentation will ultimately make you a better at both photography and post-processing (I really should take some of my own medicine....).  All that said, you have some wonderful photos in your portfolio; Pensive is gorgeous!', '2008-03-08 13:02:43.000000', NULL, 0),
(4548321, 645960, 30982, '<td valign="top">I like the grandeur and the warmth you created with this shot.  And yes, HDR creates its own noise in addition to amplifying anything you may have had already.</td>', 'I like the grandeur and the warmth you created with this shot.  And yes, HDR creates its own noise in addition to amplifying anything you may have had already.', '2008-03-08 13:04:39.000000', NULL, 0),
(4548327, 652719, 30982, '<td valign="top">The John Deere folks would probably love to have a copy of this - very vibrant - a nice "portrait" of the machine.</td>', 'The John Deere folks would probably love to have a copy of this - very vibrant - a nice "portrait" of the machine.', '2008-03-08 13:06:32.000000', NULL, 0),
(4548332, 645486, 30982, '<td valign="top">I like the simplicity of this - in composition and in color scheme.  I think it makes for a nice snippet of winter from a child''s perspective.</td>', 'I like the simplicity of this - in composition and in color scheme.  I think it makes for a nice snippet of winter from a child''s perspective.', '2008-03-08 13:08:48.000000', NULL, 0),
(4548339, 652442, 30982, '<td valign="top">Ah, from Julianne''s comment I see that this is indeed a sculpture - I thought it was, but couldn''t figure out the water splashes!  Great angle and exposure on this - a very captivating shot.</td>', 'Ah, from Julianne''s comment I see that this is indeed a sculpture - I thought it was, but couldn''t figure out the water splashes!  Great angle and exposure on this - a very captivating shot.', '2008-03-08 13:11:13.000000', NULL, 0),
(4548342, 652978, 30982, '<td valign="top">I thought I''d seen this before somewhere... :-)  I particularly like the way you use your hair as framing.</td>', 'I thought I''d seen this before somewhere... :-)  I particularly like the way you use your hair as framing.', '2008-03-08 13:12:43.000000', NULL, 0),
(4548348, 649244, 30982, '<td valign="top">Wonderful vibrant color!  And yes, shooting at midday or in bright sunshine can give harsh shadows, but sometimes the colors are just so gorgeous then.</td>', 'Wonderful vibrant color!  And yes, shooting at midday or in bright sunshine can give harsh shadows, but sometimes the colors are just so gorgeous then.', '2008-03-08 13:16:02.000000', NULL, 0),
(4548351, 653110, 30982, '<td valign="top">Wonderful shot!  ''Grats on an outstanding score and a top twenty in a Free Study - that''s an excellent achievement!  (Then again, getting this shot in the first place is one heck of an achievement all by itself!)</td>', 'Wonderful shot!  ''Grats on an outstanding score and a top twenty in a Free Study - that''s an excellent achievement!  (Then again, getting this shot in the first place is one heck of an achievement all by itself!)', '2008-03-08 13:17:35.000000', NULL, 0),
(4548354, 649085, 30982, '<td valign="top">Hey young lady!  I was wondering if that was you!  Now a question - is that a wedding ring on your hand??</td>', 'Hey young lady!  I was wondering if that was you!  Now a question - is that a wedding ring on your hand??', '2008-03-08 13:18:44.000000', NULL, 0),
(4548356, 652297, 30982, '<td valign="top">Way, way underappreciated by the voting masses.  This is lovely.</td>', 'Way, way underappreciated by the voting masses.  This is lovely.', '2008-03-08 13:20:37.000000', NULL, 0),
(4548360, 652965, 53814, '<td valign="top">This is great art Karen. Congratulations on the Yellow ribbon.</td>', 'This is great art Karen. Congratulations on the Yellow ribbon.', '2008-03-08 13:23:06.000000', NULL, 0),
(4548365, 648777, 52296, '<td valign="top">Congrats on the blue Owen (and your new camera), this is a wonderful shot, be proud!!</td>', 'Congrats on the blue Owen (and your new camera), this is a wonderful shot, be proud!!', '2008-03-08 13:24:15.000000', NULL, 0),
(4548368, 653066, 45672, '<td valign="top">Awesome shot.  I know this area pretty well and you''ve captured an amazing shot.  Congratulations!</td>', 'Awesome shot.  I know this area pretty well and you''ve captured an amazing shot.  Congratulations!', '2008-03-08 13:26:03.000000', NULL, 0),
(4548404, 652640, 50695, '<td valign="top">been in this park many times and never managed to find a good picture in it. bravo.</td>', 'been in this park many times and never managed to find a good picture in it. bravo.', '2008-03-08 13:44:58.000000', NULL, 0),
(4548417, 652576, 50695, '<td valign="top">It''s funny to hear people give you advice about how to make a picture of an ugly girder on the beach more pretty. That would be like putting pearls on a pig. Let pearls be pearls and pigs be pigs. This is a glorious ugly pig that got 3 10s, 2 9s and 2 8s. I was one of your 10s. You did very well.</td>', 'It''s funny to hear people give you advice about how to make a picture of an ugly girder on the beach more pretty. That would be like putting pearls on a pig. Let pearls be pearls and pigs be pigs. This is a glorious ugly pig that got 3 10s, 2 9s and 2 8s. I was one of your 10s. You did very well.', '2008-03-08 13:51:55.000000', NULL, 0),
(4548425, 652576, 75192, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by posthumous:</b></div><hr/><i> It''s funny to hear people give you advice about how to make a picture of an ugly girder on the beach more pretty. That would be like putting pearls on a pig. Let pearls be pearls and pigs be pigs. This is a glorious ugly pig that got 3 10s, 2 9s and 2 8s. I was one of your 10s. You did very well. </i></td></tr></table> <br/> <br/>The reason I entered it, was because I thought it was very beautiful. I could have entered a slow running lake or the ocean, but I went for the girder. I''m much more into wabi sabi than common perceptions of beauty. <br/> <br/>You rock PH. <br/> <br/>Thanks everyone for your comments *hug*</td>', 'Originally posted by posthumous: It''s funny to hear people give you advice about how to make a picture of an ugly girder on the beach more pretty. That would be like putting pearls on a pig. Let pearls be pearls and pigs be pigs. This is a glorious ugly pig that got 3 10s, 2 9s and 2 8s. I was one of your 10s. You did very well.   The reason I entered it, was because I thought it was very beautiful. I could have entered a slow running lake or the ocean, but I went for the girder. I''m much more into wabi sabi than common perceptions of beauty.  You rock PH.  Thanks everyone for your comments *hug*', '2008-03-08 13:58:01.000000', NULL, 0),
(4548426, 652897, 19978, '<td valign="top">Exquisite!! I''ve been watching you show up time after time in the top 4 or 5. I can see why. Very outstanding stuff!</td>', 'Exquisite!! I''ve been watching you show up time after time in the top 4 or 5. I can see why. Very outstanding stuff!', '2008-03-08 13:58:09.000000', NULL, 0),
(4548427, 649537, 50695, '<td valign="top">I gave you a 9. For someone who''s "not an artist," you have an amazing sense of composition.</td>', 'I gave you a 9. For someone who''s "not an artist," you have an amazing sense of composition.', '2008-03-08 13:58:38.000000', NULL, 0),
(4548430, 652565, 50695, '<td valign="top">I gave this a 9. I underrated it.</td>', 'I gave this a 9. I underrated it.', '2008-03-08 13:59:14.000000', NULL, 0),
(4548463, 650253, 18450, '<td valign="top">Beautiful intimate and loving portrait Aimee! It''s absolutely gorgeous!!</td>', 'Beautiful intimate and loving portrait Aimee! It''s absolutely gorgeous!!', '2008-03-08 14:21:23.000000', NULL, 0),
(4548475, 643626, 64568, '<td valign="top">This was a 10 from me, I was sure it would ribbon, but great score nevertheless. Beautiful aurora and silky landscape, nice one ;-)</td>', 'This was a 10 from me, I was sure it would ribbon, but great score nevertheless. Beautiful aurora and silky landscape, nice one ;-)', '2008-03-08 14:28:36.000000', NULL, 0),
(4548479, 652921, 64568, '<td valign="top">I gave 3 10''s in this free study and this was one of them, beautiful capture, great lighting and bokeh, nice one ;-)</td>', 'I gave 3 10''s in this free study and this was one of them, beautiful capture, great lighting and bokeh, nice one ;-)', '2008-03-08 14:30:26.000000', NULL, 0),
(4548516, 647945, 53814, '<td valign="top">Wonderful shot, beautiful model!</td>', 'Wonderful shot, beautiful model!', '2008-03-08 14:48:54.000000', NULL, 0),
(4548528, 652893, 29011, '<td valign="top">I 2nd Brad, very precious and charming capture. What great pals these two must be.</td>', 'I 2nd Brad, very precious and charming capture. What great pals these two must be.', '2008-03-08 15:02:02.000000', NULL, 0),
(4548540, 651432, 41521, '<td valign="top">This is fabulous, outstanding color.  Shame about the DQ.</td>', 'This is fabulous, outstanding color.  Shame about the DQ.', '2008-03-08 15:10:17.000000', NULL, 0),
(4548546, 647945, 19708, '<td valign="top">This has such a natural and comfortable look &amp; feel to it.<br/>Just a moment, a natural moment that is one of daily enjoyment and as seen on any given day.<br/>The real value of this is the lack of fancy setups and was done in familiar surroundings.<br/>Very nicely done and this is exactly the type of portrait photograph that I could see on the inside flap of a book.<br/>Bravo!</td>', 'This has such a natural and comfortable look & feel to it.Just a moment, a natural moment that is one of daily enjoyment and as seen on any given day.The real value of this is the lack of fancy setups and was done in familiar surroundings.Very nicely done and this is exactly the type of portrait photograph that I could see on the inside flap of a book.Bravo!', '2008-03-08 15:12:35.000000', NULL, 0),
(4548555, 651432, 164, '<td valign="top">Very nice. I like what you did to the picture even if the SC didn''t.</td>', 'Very nice. I like what you did to the picture even if the SC didn''t.', '2008-03-08 15:15:52.000000', NULL, 0),
(4548557, 649556, 77262, '<td valign="top">I love the sharpness of it how did u do that?</td>', 'I love the sharpness of it how did u do that?', '2008-03-08 15:18:11.000000', NULL, 0),
(4548568, 641531, 49109, '<td valign="top">beautiful view, especially the cloudscape. love the almost horizontal light from the right. Totle doen''t fit too well, IMO, the overall tone is too warm. were also gone for a tad more saturation and contrast.</td>', 'beautiful view, especially the cloudscape. love the almost horizontal light from the right. Totle doen''t fit too well, IMO, the overall tone is too warm. were also gone for a tad more saturation and contrast.', '2008-03-08 15:29:05.000000', NULL, 0),
(4548592, 645335, 31606, '<td valign="top">29th place is great but IMO you were robbed.  This image is much better than most in front of you.  Very nice image.  How about some shot details?<br/><br/><i>Message edited by author 2008-03-08 15:46:46.</i></td>', '29th place is great but IMO you were robbed.  This image is much better than most in front of you.  Very nice image.  How about some shot details?', '2008-03-08 15:46:27.000000', '2008-03-08 15:46:46.000000', 0),
(4548607, 652893, 16241, '<td valign="top">awesome...!</td>', 'awesome...!', '2008-03-08 15:52:44.000000', NULL, 0),
(4548633, 652868, 68504, '<td valign="top">Like magic.  (Great story).</td>', 'Like magic.  (Great story).', '2008-03-08 16:16:08.000000', NULL, 0),
(4548634, 652565, 60173, '<td valign="top">When I was browsing through this challenge I came to your photo, paused for a second, and then fell in love with it. It''s absolutely beautiful. I love how the hair nearly fills every corner. The corner it doesn''t touch is your ground. Being the darkest part of your photo it gives the eye something to hold on to with all the craziness going on. While the pink cast of the hair seems a bit unnatural, it''s melds well with the other colors in the photo. <br/> <br/>Overall, there''s almost a sense of mystery. You can''t clearly see her eye, and that creates a natural intrigue. I find myself wanting to part her hair and touch what is obviously a baby soft rosy cheek. I would feel weird about hanging someone else''s kid on my wall, but if this were my kid she''d be on a full sized canvas. I''d hang her in my entrance so everyone could see what a beautiful child I had and what a great photographer I was!</td>', 'When I was browsing through this challenge I came to your photo, paused for a second, and then fell in love with it. It''s absolutely beautiful. I love how the hair nearly fills every corner. The corner it doesn''t touch is your ground. Being the darkest part of your photo it gives the eye something to hold on to with all the craziness going on. While the pink cast of the hair seems a bit unnatural, it''s melds well with the other colors in the photo.  Overall, there''s almost a sense of mystery. You can''t clearly see her eye, and that creates a natural intrigue. I find myself wanting to part her hair and touch what is obviously a baby soft rosy cheek. I would feel weird about hanging someone else''s kid on my wall, but if this were my kid she''d be on a full sized canvas. I''d hang her in my entrance so everyone could see what a beautiful child I had and what a great photographer I was!', '2008-03-08 16:17:00.000000', NULL, 0),
