(4550226, 652897, 23430, '<td valign="top">You have awesome clarity in your Macros Irene. Truly something to aim for.</td>', 'You have awesome clarity in your Macros Irene. Truly something to aim for.', '2008-03-09 15:30:55.000000', NULL, 0),
(4550252, 652480, 39429, '<td valign="top">Gorgeous - I really love the mood here.</td>', 'Gorgeous - I really love the mood here.', '2008-03-09 15:46:11.000000', NULL, 0),
(4550434, 652868, 66384, '<td valign="top">I love the sharp brown clarity of the hares in the pale blue surrounding of the frosty day. The DOF and focus seem to be perfect, and the action is fascinating. Congratulations on the very high placement in this crowded challenge.<br/> <br/>BTW, Deb said it was one of her top ten for the challenge. I have a special "Deb''s Top Ten" sucker on my profile page. Grab it if you''d like.</td>', 'I love the sharp brown clarity of the hares in the pale blue surrounding of the frosty day. The DOF and focus seem to be perfect, and the action is fascinating. Congratulations on the very high placement in this crowded challenge. BTW, Deb said it was one of her top ten for the challenge. I have a special "Deb''s Top Ten" sucker on my profile page. Grab it if you''d like.', '2008-03-09 17:23:07.000000', NULL, 0),
(4550448, 650095, 66384, '<td valign="top">These rich colors are beautiful. I love the mood of this scene. And the tiny touch of red on the hikers is just right for giving the eye an anchor. I like the way the hikers are ascending the path leading to the large vertical stone which points slightly over toward the mountains. The flow in the image is great. Although it doesn''t need it, I would have been tempted to brighten up the valley a little with a touch of ''soft light'' white or yellow paint.</td>', 'These rich colors are beautiful. I love the mood of this scene. And the tiny touch of red on the hikers is just right for giving the eye an anchor. I like the way the hikers are ascending the path leading to the large vertical stone which points slightly over toward the mountains. The flow in the image is great. Although it doesn''t need it, I would have been tempted to brighten up the valley a little with a touch of ''soft light'' white or yellow paint.', '2008-03-09 17:32:54.000000', NULL, 0),
(4550495, 648777, 31889, '<td valign="top">Woot!  Well done Owen.</td>', 'Woot!  Well done Owen.', '2008-03-09 18:00:03.000000', NULL, 0),
